    capturedAt: new Date().toISOString(),
    revision: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(),
    status: execFileSync('git', ['status', '--porcelain=v1'], { cwd: root, encoding: 'utf8', maxBuffer: 4 * 1024 * 1024 }),
